  'admin/domain/help_tip' => 'ヒント情報：<br>
        1、この機能は、非静的モードで、同じデータベース、異なるドメインで異なるテンプレートとWebサイト構成情報を表示することをサポートしています<br>
        2、ドメインWebサイトの数に制限はありません<br>
        3、インポートテキストの形式は次のとおりです。ドメイン$Webサイト名$キーワード$説明$テンプレート$テンプレートディレクトリ$広告ディレクトリ$マップディレクトリ$モバイルテンプレート$モバイルステーションのドメイン。Webサイトごとに1行。元のデータをクリアします。<br>
        4、マップディレクトリが設定されている場合、管理者はnginxのリダイレクトを自身で設定する必要があります。URLは次のとおりです：rss/$マップディレクトリ/index.xml。<br>
        5、モバイルテンプレートを空にすると、そのサイトではモバイルテンプレートを使用しません。モバイルステーションのドメインは「モバイルに適応＝マルチドメイン」の場合のみ有効で、そのドメインにモバイルからアクセスするとそのサイトのモバイルテンプレートが使用されます。',
