        3.ルーティングアドレスはシステムによって提供され、原則として変更されません。ルーティング式を調整するだけです。<br>
        4.余分な空行を入れないでください。<br>
        5.IDタイプは必要に応じて選択してください。ピンインを選択する場合、データに重複するピンインを含めることはできません。そうしないと、データの取得に問題が発生します。<br>
        6.URL区切り文字は/と-をサポートしています。他の記号を使用することはお勧めしません。',
